import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"使用 Lab 与资产库","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/guides/lab-viewer","contentType":"guide","prev":{"text":"快速开始","link":"/getting-started/quickstart"},"next":{"text":"持久数字资产","link":"/tutorials/persistent-assets"}},"headers":[],"relativePath":"guides/lab-viewer.md","filePath":"guides/lab-viewer.md"}'),l={name:"guides/lab-viewer.md"};function r(n,a,p,h,d,o){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="使用-lab-与资产库" tabindex="-1">使用 Lab 与资产库 <a class="header-anchor" href="#使用-lab-与资产库" aria-label="Permalink to &quot;使用 Lab 与资产库&quot;">​</a></h1><p>目标：在正式应用中查看设备模型、导入本地 GLB，并从资产库再次打开。Lab 复用现有身份与应用壳，三维代码按页面加载。</p><h2 id="正式应用" tabindex="-1">正式应用 <a class="header-anchor" href="#正式应用" aria-label="Permalink to &quot;正式应用&quot;">​</a></h2><p>从仓库根目录启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>，登录开发账号或从 <code>/register</code> 注册。登录和注册后默认进入 Lab。<code>just dev</code> 启动平台服务并执行迁移，沿用本地开发数据；它不是隔离测试环境。</p><ol><li>Lab 主入口创建和打开持久实验室，使用对象目录、场景与 Inspector。完整登记步骤见<a href="./../tutorials/persistent-world">持久 Lab 与对象教程</a>。</li><li>从资产库选择预置工业显微镜并在 Lab 中打开，进入 <code>/lab/asset</code> 单模型预览。旋转、缩放、平移；聚焦保持当前方向，重置恢复初始方向。点击模型选择，点击空白清除选择。</li><li>选择或拖入资源完整内嵌的 glTF 2.0 <code>.glb</code>，模型自动居中与取景，原始尺度保留。</li><li>在资产库导入时填写名称、来源、许可和版本，发布后搜索名称或文件名，打开模型到 Lab，或确认删除未引用资产。</li><li>导入损坏文件应显示失败反馈并保留前一个可用模型，随后仍能成功导入有效文件。</li></ol><p>资产库与 GLB 字节持久保存在服务器。刷新或换浏览器后可以重新打开。内置定义提供规格、能力与状态结构。后端照明、温度传感器与离心任务已实现。<a href="./../tutorials/run-history">运行历史</a>提供时间筛选、分页、缺口与保留策略。<a href="./../tutorials/persistent-assets">资产教程</a>提供导入和恢复操作。旧知识库路由保留原有含义。视口显示实时渲染计数与可用 JS heap。它不采样 GPU 时间，也不测量显存字节数。</p><p>源码见<a href="https://github.com/CaiZongyuan/labworld/blob/f2b03d9e824f4ec0baeb5e5c054a43edc82a609c/apps/web/src/app-examples.tsx" target="_blank" rel="noreferrer">业务组装</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/f2b03d9e824f4ec0baeb5e5c054a43edc82a609c/packages/views/src/lab/app-example.tsx" target="_blank" rel="noreferrer">Lab 贡献</a>和<a href="https://github.com/CaiZongyuan/labworld/blob/f2b03d9e824f4ec0baeb5e5c054a43edc82a609c/packages/views/src/lab/lab-view.tsx" target="_blank" rel="noreferrer">查看页</a>。<a href="https://github.com/CaiZongyuan/labworld/blob/f2b03d9e824f4ec0baeb5e5c054a43edc82a609c/assets/README.md" target="_blank" rel="noreferrer">素材记录</a>保留原件、运行文件和许可。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/perf-bundle.mjs</span></span></code></pre></div><p>页面测试负责目录、导航、导入反馈和移除。真实 WebGL、相机、点选与资源生命周期在浏览器验证。后台启动服务时将日志写在应用监听目录之外，避免控制台输出引发刷新循环。</p><h2 id="历史-v1-预览" tabindex="-1">历史 v1 预览 <a class="header-anchor" href="#历史-v1-预览" aria-label="Permalink to &quot;历史 v1 预览&quot;">​</a></h2><p>需要 Node、pnpm、桌面 Chrome，以及本地的 <code>.scratch/lab-viewer/v1/</code>。完整版本由本地 <code>preview/lab-viewer-v1</code> 分支保存，提交为 <code>9439a1de78c5433795d22a03e3e6086540832794</code>。它不在主分支的源码目录内；只有主分支时不能执行下述启动命令。此预览分支当前保存在本地，线上可用性需在实际发布后核对。</p><p>已有版本目录时，从仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>默认打开 <a href="http://127.0.0.1:5190/prototype/lab-viewer" target="_blank" rel="noreferrer">http://127.0.0.1:5190/prototype/lab-viewer</a>，端口占用时以 Vite 输出为准。该入口不需要 API 或数据库，不写入正式应用数据。</p><p>如果本地分支存在但版本目录缺失，可在独立工作树取得预览：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../lab-word-preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview/lab-viewer-v1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../lab-word-preview/.scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../lab-word-preview/.scratch/lab-viewer/v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><h2 id="观察一次完整操作" tabindex="-1">观察一次完整操作 <a class="header-anchor" href="#观察一次完整操作" aria-label="Permalink to &quot;观察一次完整操作&quot;">​</a></h2><ol><li>首次打开应看到显微镜及环境光照，不是空白画布。</li><li>旋转、缩放、平移，再聚焦或重置视角；点击设备查看静态资产信息，点击空白清除选择。</li><li>用文件选择或拖拽导入资源内嵌的 glTF 2.0 <code>.glb</code>，新模型自动居中与取景。</li><li>导入无效文件或引用缺失资源的 GLB，应出现明确失败反馈并保留前一个可用模型；随后仍能成功导入有效 GLB。</li><li>查看 FPS、draw calls、triangles 与资源计数。JS heap 和 GPU 时间不同于对象数量；不可获取的指标显示不可用。</li></ol><p>本地文件仅用于当前浏览器会话，不上传到服务端；刷新不保证恢复导入文件。v1 每次查看一个模型，尚无场景摆放编辑。</p><h2 id="资产与证据" tabindex="-1">资产与证据 <a class="header-anchor" href="#资产与证据" aria-label="Permalink to &quot;资产与证据&quot;">​</a></h2><p>预置设备为 Poly Haven 的 <a href="https://polyhaven.com/a/industrial_microscope" target="_blank" rel="noreferrer">Industrial Microscope</a>，作者 Lukas Walzer，CC0；环境为 <a href="https://polyhaven.com/a/studio_small_03" target="_blank" rel="noreferrer">Studio Small 03</a>，作者 Greg Zaal，CC0。来源、原始文件和运行 GLB/HDR 随预览版本保存。</p><p>此前 Chromium/SwiftShader 已验证实际渲染、导入、选择、相机和错误恢复。软件渲染的 FPS 不是实际 GPU 性能验收；预览包体也不是生产预算结果。<a href="https://github.com/CaiZongyuan/labworld/blob/f2b03d9e824f4ec0baeb5e5c054a43edc82a609c/docs/ui/lab-viewer-experience.md" target="_blank" rel="noreferrer">体验记录</a>保留具体范围与证据。</p><p>历史预览使用模拟身份与导航。已接受的设计为当前应用提供输入。正式路由、持久导入、布局编辑、设备任务、历史和<a href="./../tutorials/entity-lifecycle">对象生命周期</a>已实现。用户可以归档已停止设备，独立替换外观。<a href="./../tutorials/complete-foundation">完整旅程</a>组合这些操作，并提供独立参考负载入口。真实设备接入仍属后续范围。见<a href="./../architecture/lab-word">产品架构</a>。</p><hr><p>源码版本：<code>f2b03d9e824f</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/f2b03d9e824f4ec0baeb5e5c054a43edc82a609c/docs/guides/lab-viewer.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,27)])])}const b=e(l,[["render",r]]);export{k as __pageData,b as default};
